using System.Collections.Generic;
using Unity.Burst;
using Unity.Collections;
using Unity.Jobs;
using Unity.Mathematics;
using UnityEngine;

[System.Flags]
public enum PreviewWorldRebuildScope { None = 0, Tectonics = 1, Climate = 2, Hydrology = 4, Biomes = 8, All = 15 }
public struct MenuPlanetPreviewWorldInputs { public float seed, landScale, landThreshold, elevation, temperature, moisture, moistureResponseScale, temperatureHumidityInfluence, climateNoiseStrength, coastWetnessStrength, continentalDrynessStrength, continentalTemperatureStrength, rainShadowStrength, orographicWetnessStrength, orographicSampleOffset, seasonalityStrength, biomeProvinceStrength, biomeCompetitionSharpness, iceCapSize; public int landPresetIndex, waterwaysPreset; }

public class MenuPlanetPreviewWorldGenerator : MonoBehaviour {
    [SerializeField] int mapWidth = 1024, mapHeight = 512; [SerializeField] float regenerationDelay = 0.15f;
    [SerializeField, Range(4, 32)] int plateCount = 14; [SerializeField, Range(0.005f, 0.25f)] float plateBoundaryWidth = 0.06f; [SerializeField, Range(0f, 1f)] float continentalPlateFraction = 0.55f;
    [SerializeField, Range(0f, 1f)] float plateShapeNoiseStrength = 0.28f; [SerializeField] float plateBoundaryWarpScale = 2.2f, plateBoundaryWarpAmplitude = 0.08f;
    [SerializeField] float minimumSeaLevel = 0.30f, maximumSeaLevel = 0.78f, continentalDetailScale = 1.65f, continentalDetailStrength = 0.22f, continentSeedStrength = 0.82f, plateContinentalInfluence = 0.16f;
    [SerializeField] float continentalElevationStrength = 0.42f, oceanBasinDepthStrength = 0.58f, convergentMountainStrength = 0.72f, divergentRidgeStrength = 0.18f, terrainDetailNoiseStrength = 0.14f, continentalShelfStrength = 0.75f, continentalShelfWidth = 0.08f;

    Texture2D tectonicSurfaceTexture, tectonicBoundaryTexture, tectonicCrustTexture, climateTexture, hydrologyMaskTexture, biomeWeights0Texture, biomeWeights1Texture, biomeWeights2Texture;
    public Texture2D TectonicSurfaceTexture => tectonicSurfaceTexture; public Texture2D TectonicBoundaryTexture => tectonicBoundaryTexture; public Texture2D TectonicCrustTexture => tectonicCrustTexture; public Texture2D ClimateTexture => climateTexture; public Texture2D HydrologyMaskTexture => hydrologyMaskTexture; public Texture2D BiomeWeights0Texture => biomeWeights0Texture; public Texture2D BiomeWeights1Texture => biomeWeights1Texture; public Texture2D BiomeWeights2Texture => biomeWeights2Texture;
    public event System.Action WorldTexturesUpdated; MenuPlanetPreviewWorldInputs inputs; PreviewWorldRebuildScope pending; float scheduledAt = -1; NativeArray<float> continentality;
    struct PreviewTectonicPlateNative { public float3 centerDir, motionDir; public float continentalBias, baseElevationBias, ruggedness, age; }
    struct PreviewContinentSeedNative { public float3 centerDir; public float radius, strength, elongation; public float3 stretchAxis; }
    public void SetInputs(MenuPlanetPreviewWorldInputs v) => inputs = v; public void RequestRebuild(PreviewWorldRebuildScope scope, bool immediate = false) { pending |= ExpandDependencies(scope); if (immediate) Flush(); else scheduledAt = Time.time + regenerationDelay; }
    void Update() { if (scheduledAt > 0 && Time.time >= scheduledAt) Flush(); }
    void Flush() { scheduledAt = -1; var s = pending; pending = PreviewWorldRebuildScope.None; if (s == PreviewWorldRebuildScope.None) return; if ((s & PreviewWorldRebuildScope.Tectonics) != 0) GenerateTectonics(); if ((s & PreviewWorldRebuildScope.Climate) != 0) GenerateClimate(); if ((s & PreviewWorldRebuildScope.Hydrology) != 0) GenerateHydrology(); if ((s & PreviewWorldRebuildScope.Biomes) != 0) GenerateBiomes(); WorldTexturesUpdated?.Invoke(); }
    PreviewWorldRebuildScope ExpandDependencies(PreviewWorldRebuildScope r) => (r & PreviewWorldRebuildScope.Tectonics) != 0 ? PreviewWorldRebuildScope.All : (r & PreviewWorldRebuildScope.Climate) != 0 ? PreviewWorldRebuildScope.Climate | PreviewWorldRebuildScope.Hydrology | PreviewWorldRebuildScope.Biomes : (r & PreviewWorldRebuildScope.Hydrology) != 0 ? PreviewWorldRebuildScope.Hydrology | PreviewWorldRebuildScope.Biomes : (r & PreviewWorldRebuildScope.Biomes) != 0 ? PreviewWorldRebuildScope.Biomes : 0;
    void Ensure(ref Texture2D t, string n) { if (t != null && t.width == mapWidth && t.height == mapHeight) return; if (t != null) Destroy(t); t = new Texture2D(mapWidth, mapHeight, TextureFormat.RGBA32, false, true) { name = n, wrapMode = TextureWrapMode.Repeat, filterMode = FilterMode.Bilinear }; }
    static byte ToByte(float v) => (byte)math.clamp(math.round(math.saturate(v) * 255f), 0, 255);
    void GenerateTectonics(){Ensure(ref tectonicSurfaceTexture,"MenuTectonicSurface");Ensure(ref tectonicBoundaryTexture,"MenuTectonicBoundary");Ensure(ref tectonicCrustTexture,"MenuTectonicCrust"); int n=mapWidth*mapHeight; var s=new NativeArray<Color32>(n,Allocator.TempJob); var b=new NativeArray<Color32>(n,Allocator.TempJob); var c=new NativeArray<Color32>(n,Allocator.TempJob);
        var plates=new NativeArray<PreviewTectonicPlateNative>(plateCount,Allocator.TempJob); var seeds=BuildSeeds(Allocator.TempJob); BuildPlates(plates);
        GetPreset(inputs.landPresetIndex,out float seaBias,out float frag); new TectJob{width=mapWidth,height=mapHeight,seed=inputs.seed,landScale=math.max(0.1f,inputs.landScale),landThreshold=inputs.landThreshold,elevation=inputs.elevation,plateBoundaryWidth=plateBoundaryWidth,plateShapeNoiseStrength=plateShapeNoiseStrength,plateBoundaryWarpScale=plateBoundaryWarpScale,plateBoundaryWarpAmplitude=plateBoundaryWarpAmplitude,minimumSeaLevel=minimumSeaLevel,maximumSeaLevel=maximumSeaLevel,continentalElevationStrength=continentalElevationStrength,oceanBasinDepthStrength=oceanBasinDepthStrength,convergentMountainStrength=convergentMountainStrength,divergentRidgeStrength=divergentRidgeStrength,terrainDetailNoiseStrength=terrainDetailNoiseStrength,continentalShelfStrength=continentalShelfStrength,continentalShelfWidth=continentalShelfWidth,continentalDetailScale=continentalDetailScale,continentalDetailStrength=continentalDetailStrength,continentSeedStrength=continentSeedStrength,plateContinentalInfluence=plateContinentalInfluence,presetSeaLevelBias=seaBias,islandFragmentStrength=frag,plates=plates,continentSeeds=seeds,surf=s,bound=b,crust=c}.Schedule(n,128).Complete();
        tectonicSurfaceTexture.SetPixelData(s,0);tectonicBoundaryTexture.SetPixelData(b,0);tectonicCrustTexture.SetPixelData(c,0);tectonicSurfaceTexture.Apply(false,false);tectonicBoundaryTexture.Apply(false,false);tectonicCrustTexture.Apply(false,false);s.Dispose();b.Dispose();c.Dispose();plates.Dispose();seeds.Dispose(); RebuildContinentality(); }
    NativeArray<PreviewContinentSeedNative> BuildSeeds(Allocator a){int count=inputs.landPresetIndex switch{0=>22,1=>15,2=>10,3=>7,4=>4,_=>3}; var arr=new NativeArray<PreviewContinentSeedNative>(count,a); var rng=new Unity.Mathematics.Random((uint)math.max(1,(int)(inputs.seed*1000)+12345)); for(int i=0;i<count;i++){float3 d=math.normalizesafe(rng.NextFloat3Direction()); arr[i]=new PreviewContinentSeedNative{centerDir=d,radius=rng.NextFloat(0.18f,0.42f),strength=rng.NextFloat(0.6f,1f),elongation=rng.NextFloat(0f,0.9f),stretchAxis=math.normalizesafe(rng.NextFloat3Direction())};} return arr;}
    void BuildPlates(NativeArray<PreviewTectonicPlateNative> plates){var rng=new Unity.Mathematics.Random((uint)math.max(1,(int)(inputs.seed*2000)+9871)); for(int i=0;i<plates.Length;i++) plates[i]=new PreviewTectonicPlateNative{centerDir=math.normalizesafe(rng.NextFloat3Direction()),motionDir=math.normalizesafe(rng.NextFloat3Direction()),continentalBias=rng.NextFloat()<continentalPlateFraction?rng.NextFloat(0.55f,1f):rng.NextFloat(0f,0.45f),ruggedness=rng.NextFloat(0.3f,1f),age=rng.NextFloat(),baseElevationBias=rng.NextFloat(-0.1f,0.1f)}; }
    void GetPreset(int p,out float sea,out float frag){(sea,frag)=p switch{0=>(0.08f,0.28f),1=>(0.04f,0.2f),2=>(0f,0.12f),3=>(-0.05f,0.08f),4=>(-0.10f,0.03f),_=>(-0.14f,0f)};}
    void RebuildContinentality(){int n=mapWidth*mapHeight;if(continentality.IsCreated)continentality.Dispose();continentality=new NativeArray<float>(n,Allocator.Persistent);var q=new Queue<int>();var raw=tectonicSurfaceTexture.GetRawTextureData<Color32>();for(int i=0;i<n;i++){if(raw[i].r<128){continentality[i]=0;q.Enqueue(i);}else continentality[i]=9999;}while(q.Count>0){int i=q.Dequeue();int x=i%mapWidth,y=i/mapWidth;float d=continentality[i]+1;int l=y*mapWidth+((x-1+mapWidth)%mapWidth),r=y*mapWidth+((x+1)%mapWidth);if(d<continentality[l]){continentality[l]=d;q.Enqueue(l);}if(d<continentality[r]){continentality[r]=d;q.Enqueue(r);}if(y>0){int u=i-mapWidth;if(d<continentality[u]){continentality[u]=d;q.Enqueue(u);}}if(y<mapHeight-1){int dn=i+mapWidth;if(d<continentality[dn]){continentality[dn]=d;q.Enqueue(dn);}}}float max=1;for(int i=0;i<n;i++)if(continentality[i]>max&&continentality[i]<9999)max=continentality[i];for(int i=0;i<n;i++)continentality[i]=math.saturate(continentality[i]/max);}    
    void GenerateClimate(){if(tectonicSurfaceTexture==null)return; Ensure(ref climateTexture,"MenuClimate"); int n=mapWidth*mapHeight; var tect=new NativeArray<Color32>(tectonicSurfaceTexture.GetRawTextureData<Color32>().ToArray(),Allocator.TempJob); var outp=new NativeArray<Color32>(n,Allocator.TempJob); new ClimateJob{width=mapWidth,height=mapHeight,seed=inputs.seed,temperature=inputs.temperature,moisture=inputs.moisture,moistureResponseScale=inputs.moistureResponseScale,temperatureHumidityInfluence=inputs.temperatureHumidityInfluence,climateNoiseStrength=inputs.climateNoiseStrength,coastWetnessStrength=inputs.coastWetnessStrength,continentalDrynessStrength=inputs.continentalDrynessStrength,continentalTemperatureStrength=inputs.continentalTemperatureStrength,rainShadowStrength=inputs.rainShadowStrength,orographicWetnessStrength=inputs.orographicWetnessStrength,orographicSampleOffset=math.max(1f,inputs.orographicSampleOffset*mapWidth),seasonalityStrength=inputs.seasonalityStrength,tect=tect,cont=continentality,outp=outp}.Schedule(n,128).Complete(); climateTexture.SetPixelData(outp,0); climateTexture.Apply(false,false); tect.Dispose(); outp.Dispose(); }
    void GenerateHydrology(){if(tectonicSurfaceTexture==null||climateTexture==null){Debug.LogError("[MenuPlanetPreviewWorldGenerator] Missing tectonic or climate data; hydrology generation aborted."); return;} Ensure(ref hydrologyMaskTexture,"MenuHydrology");
        int n=mapWidth*mapHeight; var land=new float[n];var h=new float[n];var mountain=new float[n];var shelf=new float[n];var rain=new float[n];var river=new float[n];var lake=new float[n];var flow=new float[n];var wet=new float[n];var depth=new float[n]; var t=tectonicSurfaceTexture.GetRawTextureData<Color32>(); var cl=climateTexture.GetRawTextureData<Color32>();
        for(int i=0;i<n;i++){land[i]=t[i].r/255f;h[i]=t[i].g/255f;mountain[i]=t[i].b/255f;shelf[i]=t[i].a/255f;rain[i]=cl[i].g/255f;} var src=PickSources(land,h,mountain,shelf,rain); foreach(var s in src) TraceRiver(s,land,h,shelf,river,lake,flow,wet,depth); BuildWetlands(land,h,river,lake,wet,rain); Blur(river);Blur(lake);Blur(wet);Blur(depth); var px=new Color32[n];for(int i=0;i<n;i++)px[i]=new Color32(ToByte(river[i]),ToByte(lake[i]),ToByte(wet[i]),ToByte(depth[i])); hydrologyMaskTexture.SetPixels32(px); hydrologyMaskTexture.Apply(false,false);}    
    List<int> PickSources(float[] land,float[] h,float[] mountain,float[] shelf,float[] rainfall){int target=inputs.waterwaysPreset==0?16:inputs.waterwaysPreset==1?34:68; var c=new List<int>(); for(int y=16;y<mapHeight-16;y+=3)for(int x=0;x<mapWidth;x+=3){int i=y*mapWidth+x; if(land[i]<0.6f||h[i]<0.35f||shelf[i]>0.2f)continue; float s=h[i]*0.45f+mountain[i]*0.20f+rainfall[i]*0.35f; if(s>0.5f)c.Add(i);} c.Sort((a,b)=>h[b].CompareTo(h[a])); var o=new List<int>(); foreach(var i in c){bool near=false;int x=i%mapWidth,y=i/mapWidth;foreach(var k in o){int ox=k%mapWidth,oy=k/mapWidth;if(Mathf.Abs(ox-x)+Mathf.Abs(oy-y)<24){near=true;break;}} if(!near){o.Add(i); if(o.Count>=target)break;}} return o;}
    bool TraceRiver(int src,float[] land,float[] h,float[] shelf,float[] river,float[] lake,float[] flow,float[] wet,float[] depth){var vis=new HashSet<int>(); int cur=src,prev=src; for(int step=0;step<900;step++){if(!vis.Add(cur))break; int x=cur%mapWidth,y=cur/mapWidth; float fv=flow[cur]+1f; float width=Mathf.Lerp(1f,4.8f,Mathf.Clamp01(fv/8f+step/650f)); Stamp(river,x,y,width,Mathf.Lerp(0.5f,0.95f,inputs.moisture)); Stamp(depth,x,y,Mathf.Lerp(0.8f,1.2f,width*0.16f),Mathf.Clamp01(0.25f+fv*0.08f+step/1200f)); flow[cur]+=1f; if(land[cur]<0.5f||shelf[cur]>0.2f)return true; int best=cur; float bestH=h[cur]; for(int ny=-1;ny<=1;ny++)for(int nx=-1;nx<=1;nx++){if(nx==0&&ny==0)continue; int yy=Mathf.Clamp(y+ny,0,mapHeight-1); int xx=(x+nx+mapWidth)%mapWidth; int ni=yy*mapWidth+xx; if(h[ni]<bestH){bestH=h[ni]; best=ni;}} if(best==cur){Stamp(lake,x,y,3f,0.8f);break;} if(river[best]>0.35f){flow[best]+=flow[cur]+1f;break;} prev=cur;cur=best;} return false;}
    void BuildWetlands(float[] land,float[] h,float[] river,float[] lake,float[] wet,float[] rain){for(int y=0;y<mapHeight;y++)for(int x=0;x<mapWidth;x++){int i=y*mapWidth+x; float nearby=0; for(int ny=-2;ny<=2;ny++)for(int nx=-2;nx<=2;nx++){int yy=Mathf.Clamp(y+ny,0,mapHeight-1);int xx=(x+nx+mapWidth)%mapWidth;int ni=yy*mapWidth+xx; nearby=Mathf.Max(nearby,Mathf.Max(river[ni],lake[ni]));} wet[i]=Mathf.Max(wet[i],nearby*Mathf.Clamp01((0.55f-h[i])*1.8f)*Mathf.Lerp(0.35f,1f,rain[i])*land[i]*0.75f);}}
    void Stamp(float[] buf,int cx,int cy,float rad,float str){int r=Mathf.CeilToInt(rad); for(int y=-r;y<=r;y++){int yy=Mathf.Clamp(cy+y,0,mapHeight-1); for(int x=-r;x<=r;x++){float d=Mathf.Sqrt(x*x+y*y)/Mathf.Max(0.001f,rad); if(d>1)continue; int xx=(cx+x+mapWidth)%mapWidth; int i=yy*mapWidth+xx; buf[i]=Mathf.Max(buf[i],(1f-d*d)*str); }}}
    void Blur(float[] b){var t=new float[b.Length];for(int y=0;y<mapHeight;y++)for(int x=0;x<mapWidth;x++){float s=0;int c=0;for(int ny=-1;ny<=1;ny++)for(int nx=-1;nx<=1;nx++){int yy=Mathf.Clamp(y+ny,0,mapHeight-1);int xx=(x+nx+mapWidth)%mapWidth;s+=b[yy*mapWidth+xx];c++;}t[y*mapWidth+x]=s/c;}System.Array.Copy(t,b,b.Length);}    
    void GenerateBiomes(){ if(tectonicSurfaceTexture==null||climateTexture==null||hydrologyMaskTexture==null)return; Ensure(ref biomeWeights0Texture,"MenuBiome0");Ensure(ref biomeWeights1Texture,"MenuBiome1");Ensure(ref biomeWeights2Texture,"MenuBiome2"); int n=mapWidth*mapHeight; var tect=new NativeArray<Color32>(tectonicSurfaceTexture.GetRawTextureData<Color32>().ToArray(),Allocator.TempJob);var climate=new NativeArray<Color32>(climateTexture.GetRawTextureData<Color32>().ToArray(),Allocator.TempJob);var hydro=new NativeArray<Color32>(hydrologyMaskTexture.GetRawTextureData<Color32>().ToArray(),Allocator.TempJob);var o0=new NativeArray<Color32>(n,Allocator.TempJob);var o1=new NativeArray<Color32>(n,Allocator.TempJob);var o2=new NativeArray<Color32>(n,Allocator.TempJob); new BiomeJob{tect=tect,climate=climate,hydro=hydro,o0=o0,o1=o1,o2=o2,seed=inputs.seed,iceCap=inputs.iceCapSize,biomeProvinceStrength=inputs.biomeProvinceStrength,biomeCompetitionSharpness=math.max(0.5f,inputs.biomeCompetitionSharpness)}.Schedule(n,128).Complete(); biomeWeights0Texture.SetPixelData(o0,0);biomeWeights1Texture.SetPixelData(o1,0);biomeWeights2Texture.SetPixelData(o2,0);biomeWeights0Texture.Apply(false,false);biomeWeights1Texture.Apply(false,false);biomeWeights2Texture.Apply(false,false); tect.Dispose();climate.Dispose();hydro.Dispose();o0.Dispose();o1.Dispose();o2.Dispose(); }
    public void Release(){if(continentality.IsCreated)continentality.Dispose();foreach(var t in new[]{tectonicSurfaceTexture,tectonicBoundaryTexture,tectonicCrustTexture,climateTexture,hydrologyMaskTexture,biomeWeights0Texture,biomeWeights1Texture,biomeWeights2Texture}) if(t!=null)Destroy(t);}    
    [BurstCompile] struct TectJob:IJobParallelFor{ public int width,height; public float seed,landScale,landThreshold,elevation,plateBoundaryWidth,plateShapeNoiseStrength,plateBoundaryWarpScale,plateBoundaryWarpAmplitude,minimumSeaLevel,maximumSeaLevel,continentalElevationStrength,oceanBasinDepthStrength,convergentMountainStrength,divergentRidgeStrength,terrainDetailNoiseStrength,continentalShelfStrength,continentalShelfWidth,continentalDetailScale,continentalDetailStrength,continentSeedStrength,plateContinentalInfluence,presetSeaLevelBias,islandFragmentStrength; [ReadOnly] public NativeArray<PreviewTectonicPlateNative> plates; [ReadOnly] public NativeArray<PreviewContinentSeedNative> continentSeeds; public NativeArray<Color32> surf,bound,crust; public void Execute(int index){int x=index%width,y=index/width; float3 d=TexelToDir(x,y,width,height); int p0=-1,p1=-1;float b0=-10,b1=-10;for(int p=0;p<plates.Length;p++){float w=(Fbm(d*plateBoundaryWarpScale+new float3(seed*0.013f+p*11.71f,seed*0.021f+p*7.37f,seed*0.017f+p*19.19f))-0.5f)*plateShapeNoiseStrength*plateBoundaryWarpAmplitude; float s=math.dot(d,plates[p].centerDir)+w; if(s>b0){b1=b0;p1=p0;b0=s;p0=p;} else if(s>b1){b1=s;p1=p;}} float delta=b0-b1; float boundary=1f-math.saturate(delta/math.max(1e-4f,plateBoundaryWidth)); var A=plates[p0]; var B=plates[math.max(0,p1)]; float3 bdir=math.normalizesafe(B.centerDir-A.centerDir,new float3(1,0,0)); float along=math.dot(A.motionDir-B.motionDir,bdir); float conv=math.saturate(-along*0.9f)*boundary; float div=math.saturate(along*0.9f)*boundary; float blend=math.saturate((b0-b1)/math.max(1e-4f,plateBoundaryWidth*2f)); float pBias=math.lerp(B.continentalBias,A.continentalBias,blend); float cNoise=Fbm(d*continentalDetailScale+new float3(seed+3.1f,seed*0.71f,seed*1.31f)); float seedField=0; for(int i=0;i<continentSeeds.Length;i++){var c=continentSeeds[i]; float sim=math.dot(d,c.centerDir); float axis=math.dot(d,c.stretchAxis); float st=math.lerp(1f,1f+c.elongation*math.abs(axis),0.5f); float dist=(1f-sim)/math.max(0.1f,st); float raw=1f-math.saturate(dist/math.max(1e-4f,c.radius)); float inf=raw*raw*(3f-2f*raw); seedField=math.max(seedField,inf*c.strength);} float pot=seedField*continentSeedStrength+(cNoise-0.5f)*(continentalDetailStrength+islandFragmentStrength)+(pBias-0.5f)*plateContinentalInfluence+conv*0.03f-div*0.04f; float continental=math.saturate(pot),oceanic=1f-continental; float shelfProx=math.saturate((continental-oceanic+continentalShelfWidth*2f)/math.max(0.01f,continentalShelfWidth*3f)); float basin=oceanic*(0.45f+0.55f*Fbm(d*(landScale*2.1f)+new float3(seed+44.1f,seed+12.2f,seed+8.3f)))*oceanBasinDepthStrength; float mountain=math.saturate(conv*(0.5f+continental*0.9f))*(0.6f+0.4f*A.ruggedness); float baseE=continental*continentalElevationStrength-basin+div*divergentRidgeStrength*oceanic+mountain*convergentMountainStrength; baseE+=(Fbm(d*(landScale*3.6f)+new float3(seed+96.2f,seed+51.8f,seed+14.4f))-0.5f)*terrainDetailNoiseStrength+(elevation-0.5f)*0.28f; float sea=math.saturate(math.lerp(minimumSeaLevel,maximumSeaLevel,landThreshold)+presetSeaLevelBias); float land=SmoothThreshold(sea-0.035f,sea+0.035f,baseE+0.5f); float shelf=oceanic*(1f-land)*shelfProx*continentalShelfStrength*math.saturate(1f-basin*1.35f); surf[index]=new Color32(ToByte(land),ToByte(math.saturate(baseE*0.8f+0.5f)),ToByte(mountain),ToByte(shelf)); bound[index]=new Color32(ToByte((float)p0/math.max(1f,plates.Length-1f)),ToByte(boundary),ToByte(conv),ToByte(div)); crust[index]=new Color32(ToByte(continental),ToByte(oceanic),ToByte(math.saturate(basin)),ToByte(math.saturate(pot)));} static float3 TexelToDir(int x,int y,int width,int height){float u=(x+0.5f)/width,v=(y+0.5f)/height;float lon=(u-0.5f)*math.PI*2f,lat=(v-0.5f)*math.PI,cl=math.cos(lat);return new float3(math.cos(lon)*cl,math.sin(lat),math.sin(lon)*cl);} static float SmoothThreshold(float e0,float e1,float x){float t=math.saturate((x-e0)/math.max(1e-6f,e1-e0));return t*t*(3f-2f*t);} static float Fbm(float3 p){float v=0,a=0.5f,f=1;for(int i=0;i<4;i++){float n=noise.snoise(new float3(p.x*f+p.y*0.67f,p.z*f+p.y*0.37f,p.z*0.23f+p.x*0.11f));v+=a*(n*0.5f+0.5f);f*=2;a*=0.5f;}return v;} }
    [BurstCompile] struct ClimateJob:IJobParallelFor{ public int width,height; public float seed,temperature,moisture,moistureResponseScale,temperatureHumidityInfluence,climateNoiseStrength,coastWetnessStrength,continentalDrynessStrength,continentalTemperatureStrength,rainShadowStrength,orographicWetnessStrength,orographicSampleOffset,seasonalityStrength; [ReadOnly] public NativeArray<Color32> tect; [ReadOnly] public NativeArray<float> cont; public NativeArray<Color32> outp; public void Execute(int i){int x=i%width,y=i/width; float land=tect[i].r/255f,h=tect[i].g/255f,m=tect[i].b/255f,c=cont[i]; float lat=math.abs(((y+0.5f)/height)*2f-1f); float3 d=TexelToDir(x,y,width,height); float noise=(Fbm(d*3.1f+new float3(seed,seed*0.7f,seed*1.3f))-0.5f); float temp=math.saturate((1f-lat)+(temperature-0.5f)*0.35f-h*0.4f+c*continentalTemperatureStrength*(temperature-0.5f)+noise*climateNoiseStrength*0.2f); float baseM=math.saturate(0.5f+(moisture-0.5f)*moistureResponseScale); float moist=baseM+(1f-c)*coastWetnessStrength*land-c*continentalDrynessStrength*land+(0.5f-math.abs(temp-0.5f))*temperatureHumidityInfluence + m*orographicWetnessStrength-m*rainShadowStrength*0.5f+noise*climateNoiseStrength*0.2f; float season=math.saturate((lat*0.75f+c*0.45f+noise*0.15f)*seasonalityStrength+(1f-seasonalityStrength)*0.5f); outp[i]=new Color32(ToByte(temp),ToByte(math.saturate(moist)),ToByte(c),ToByte(season)); } static float3 TexelToDir(int x,int y,int width,int height){float u=(x+0.5f)/width,v=(y+0.5f)/height;float lon=(u-0.5f)*math.PI*2f,lat=(v-0.5f)*math.PI,cl=math.cos(lat);return new float3(math.cos(lon)*cl,math.sin(lat),math.sin(lon)*cl);} static float Fbm(float3 p){float v=0,a=0.5f,f=1;for(int i=0;i<4;i++){float n=noise.snoise(new float3(p.x*f+p.y*0.67f,p.z*f+p.y*0.37f,p.z*0.23f+p.x*0.11f));v+=a*(n*0.5f+0.5f);f*=2;a*=0.5f;}return v;} }
    [BurstCompile] struct BiomeJob:IJobParallelFor{ [ReadOnly] public NativeArray<Color32> tect,climate,hydro; public NativeArray<Color32> o0,o1,o2; public float seed,biomeProvinceStrength,biomeCompetitionSharpness,iceCap; public void Execute(int i){ float land=tect[i].r/255f;if(land<0.5f){o0[i]=o1[i]=o2[i]=new Color32();return;} float h=tect[i].g/255f,mtn=tect[i].b/255f,t=climate[i].r/255f,mo=climate[i].g/255f,se=climate[i].a/255f,river=hydro[i].r/255f,lake=hydro[i].g/255f,wet=hydro[i].b/255f; float em=math.saturate(mo+river*0.12f+lake*0.2f+wet*0.35f); float province=math.sin((i+seed)*0.002f)*biomeProvinceStrength; float jungle=math.saturate((t-0.55f)*2f)*math.saturate((em-0.65f)*2f)*(1f-se*0.5f); float desert=math.saturate((1f-em)*1.6f)*math.saturate((t-0.45f)*1.8f)*(1f-wet); float sav=math.saturate((t-0.5f)*1.8f)*(1f-math.abs(em-0.5f)*2f); float tg=(1f-math.abs(t-0.52f)*2f)*(1f-math.abs(em-0.45f)*2f); float tf=(1f-math.abs(t-0.5f)*2f)*math.saturate((em-0.45f)*1.8f); float ta=(1f-math.abs(t-0.35f)*3f)*math.saturate((em-0.35f)*1.4f); float tun=math.saturate((0.4f-t)*3f); float snow=math.saturate((0.32f-t)*3f+h*0.3f+mtn*0.25f+iceCap*0.4f); float pol=math.saturate((0.25f-t)*4f)*math.saturate(snow+0.2f); float marsh=wet*math.saturate(em)*math.saturate(1f-snow); float alp=math.saturate((mtn*0.7f+h*0.5f)-em*0.25f); jungle*=1f+province*0.15f;desert*=1f-province*0.1f;tf*=1f+province*0.1f;tg*=1f-province*0.08f; float sh=biomeCompetitionSharpness; jungle=math.pow(math.max(0,jungle),sh);desert=math.pow(math.max(0,desert),sh);sav=math.pow(math.max(0,sav),sh);tg=math.pow(math.max(0,tg),sh);tf=math.pow(math.max(0,tf),sh);ta=math.pow(math.max(0,ta),sh);tun=math.pow(math.max(0,tun),sh);pol=math.pow(math.max(0,pol),sh);marsh=math.pow(math.max(0,marsh),sh); float sum=jungle+desert+sav+tg+tf+ta+tun+pol+marsh+1e-5f; o0[i]=new Color32(ToByte(jungle/sum),ToByte(desert/sum),ToByte(sav/sum),ToByte(tg/sum)); o1[i]=new Color32(ToByte(tf/sum),ToByte(ta/sum),ToByte(tun/sum),ToByte(pol/sum));